"""build_tokens.py - one source (tokens/tokens.json) -> CSS variables, iOS Swift, Android XML, the shipped CSS (@font-face + fallback
metrics), and a WCAG 2.2 contrast report. Fails (exit 1) if any contrast pair misses AA. Deterministic."""
import json, os, sys, urllib.parse
from fontTools.ttLib import TTFont
ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), '..'))
T = json.load(open(os.path.join(ROOT, 'tokens/tokens.json')))
P, S, C = T['primitive'], T['semantic'], T['component']
v = lambda d: d['$value']
os.makedirs(os.path.join(ROOT, 'tokens/dist'), exist_ok=True); os.makedirs(os.path.join(ROOT, 'css'), exist_ok=True)

# ------------------------------------------------------------------ WCAG contrast
def lin(c): c /= 255; return c / 12.92 if c <= 0.03928 else ((c + 0.055) / 1.055) ** 2.4
def lum(h): h = h.lstrip('#'); r, g, b = (int(h[i:i + 2], 16) for i in (0, 2, 4)); return 0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(b)
def ratio(a, b): la, lb = sorted((lum(a), lum(b)), reverse=True); return (la + 0.05) / (lb + 0.05)
def col(mode, name): return P['color'][mode][S['color'][mode][name]]
PAIRS = [('textPrimary', 'surface', 4.5), ('textPrimary', 'surfaceRaised', 4.5), ('textSecondary', 'surface', 4.5), ('textSecondary', 'surfaceRaised', 4.5),
         ('accent', 'surface', 4.5), ('onAccent', 'accent', 4.5), ('danger', 'surface', 4.5), ('border', 'surface', 3.0), ('focus', 'surface', 3.0), ('focus', 'surfaceRaised', 3.0), ('accent', 'surfaceRaised', 4.5)]
rep = {}; bad = []
for mode in ('light', 'dark'):
    for fg, bg, need in PAIRS:
        r = ratio(col(mode, fg), col(mode, bg)); rep['%s: %s on %s' % (mode, fg, bg)] = dict(fg=col(mode, fg), bg=col(mode, bg), ratio=round(r, 2), required=need, pass_=bool(r >= need))
        if r < need: bad.append((mode, fg, bg, round(r, 2), need))
json.dump(dict(standard='WCAG 2.2 AA (4.5:1 text, 3:1 large text / UI components / focus indicators)', pairs=rep, failures=bad), open(os.path.join(ROOT, 'reports/contrast.json'), 'w'), indent=1)

# ------------------------------------------------------------------ CSS variables
def ref(role, key):
    t = S['type'][role]
    return dict(size=v(P['font']['size'][t['size']]), lh=v(P['font']['lineHeight'][t['lineHeight']]), w=v(P['font']['weight'][t['weight']]), tr=v(P['font']['tracking'][t['tracking']]), f=t.get('features'))
css = ['/* GENERATED by tokens/build_tokens.py from tokens/tokens.json - do not edit */', ':root{', '  --sx-font: "Synthetix UI", "Synthetix UI Fallback", system-ui, sans-serif;']
for mode_sel, mode, extra in ((':root', 'light', ''), ):
    for k, val in S['color']['light'].items(): css.append('  --sx-color-%s: %s;' % (k, col('light', k)))
css.append('  --sx-wght-regular: 400; --sx-wght-medium: 500; --sx-wght-semibold: 600;'); css.append('  color-scheme: light dark;'); css.append('}')
dark = ['  --sx-color-%s: %s;' % (k, col('dark', k)) for k in S['color']['dark']] + ['  --sx-wght-medium: %s; --sx-wght-semibold: %s;' % (v(P['font']['weight']['medium-dark']), v(P['font']['weight']['semibold-dark']))]
css += ['@media (prefers-color-scheme: dark){ :root:not([data-theme="light"]){', *dark, '} }', ':root[data-theme="dark"]{', *dark, '}']
for role in S['type']:
    r = ref(role, role); wname = S['type'][role]['weight']
    wvar = {'regular': 'var(--sx-wght-regular)', 'medium': 'var(--sx-wght-medium)', 'semibold': 'var(--sx-wght-semibold)'}[wname]
    css.append('.sx-%s{font-family:var(--sx-font);font-size:%s;line-height:%s;font-weight:%s;letter-spacing:%s;%s}' % (role, r['size'], r['lh'], wvar, r['tr'], ('font-variant-numeric:tabular-nums;' if r['f'] == 'tnum' else '')))
css.append('.sx-tnum{font-variant-numeric:tabular-nums}.sx-zero{font-feature-settings:"zero"}.sx-id{font-feature-settings:"ss13","zero","tnum"}')
css.append('@media (prefers-reduced-motion: reduce){*{animation-duration:.001ms!important;transition-duration:.001ms!important;scroll-behavior:auto!important}}')
css.append(':focus-visible{outline:3px solid var(--sx-color-focus);outline-offset:2px}')
open(os.path.join(ROOT, 'tokens/dist/tokens.css'), 'w').write('\n'.join(css) + '\n')

# ------------------------------------------------------------------ fallback metrics (size-adjust against Arial-metric Liberation Sans)
FREQ = dict(zip('etaoinshrdlcumwfgypbvkjxqz', [12.7, 9.06, 8.17, 7.51, 6.97, 6.75, 6.33, 6.09, 5.99, 4.25, 4.03, 2.78, 2.76, 2.41, 2.36, 2.23, 2.02, 1.97, 1.93, 1.49, 0.98, 0.77, 0.15, 0.15, 0.1, 0.07])); SPACE = 18.0
def avg_adv(path):
    f = TTFont(path); cm = f.getBestCmap(); hm = f['hmtx']; upm = f['head'].unitsPerEm
    tot = sum(FREQ[c] * hm[cm[ord(c)]][0] for c in FREQ) + SPACE * hm[cm[32]][0]; return tot / (sum(FREQ.values()) + SPACE) / upm
fb = TTFont('/usr/share/fonts/truetype/liberation/LiberationSans-Regular.ttf') if os.path.exists('/usr/share/fonts/truetype/liberation/LiberationSans-Regular.ttf') else None
sx = os.path.join(ROOT, 'fonts/ttf/SynthetixUI-Regular.ttf'); f = TTFont(sx); hh = f['hhea']; upm = f['head'].unitsPerEm
adj = avg_adv(sx) / avg_adv('/usr/share/fonts/truetype/liberation/LiberationSans-Regular.ttf') if fb else 1.0
fallback = '@font-face{font-family:"Synthetix UI Fallback";src:local("Arial"),local("Liberation Sans"),local("Helvetica");size-adjust:%.1f%%;ascent-override:%.1f%%;descent-override:%.1f%%;line-gap-override:%.1f%%}' % (
    adj * 100, hh.ascent / upm / adj * 100, -hh.descent / upm / adj * 100, hh.lineGap / upm / adj * 100)

# ------------------------------------------------------------------ shipped CSS
import re
sub = json.load(open(os.path.join(ROOT, 'reports/subset_sizes.json'))) if os.path.exists(os.path.join(ROOT, 'reports/subset_sizes.json')) else {}
sys.path.insert(0, os.path.join(ROOT, 'build'))
RANGES = {'latin-lite': 'U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+2044,U+20A6,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD', 'latin': 'U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+2044,U+20A6,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD',
          'latin-ext': 'U+0100-02BA,U+02BD-02C5,U+02C7-02CC,U+02CE-02D7,U+02DD-02FF,U+0304,U+0308,U+0329,U+1D00-1DBF,U+1E00-1E9F,U+1EF2-1EFF,U+2020,U+20A0-20A5,U+20A7-20AB,U+20AD-20C0,U+2113,U+2C60-2C7F,U+A720-A7FF',
          'african': 'U+0181,U+0186,U+018A,U+0190,U+0198-0199,U+01B3-01B4,U+01F8-01F9,U+0253-0254,U+0257,U+025B,U+02BC,U+0300-0304,U+0306-0308,U+030C,U+0323,U+1E3E-1E3F,U+1E44-1E45,U+1E62-1E63,U+1EB8-1EB9,U+1ECA-1ECD,U+1EE4-1EE5,U+014A-014B',
          'symbols': 'U+2070-209F,U+2116,U+2153-215B,U+2190-2195,U+2248,U+2260,U+2264-2265,U+221E,U+2713,U+20B5,U+20B9,U+2044'}
q = lambda p: urllib.parse.quote(p, safe='/')
head = '/* Synthetix UI %s - GENERATED by tokens/build_tokens.py. Paths are relative to this file. License: SIL OFL 1.1 (see fonts/OFL.txt). */\n' % json.load(open(os.path.join(ROOT, 'build/config.json')))['semver']
vf = [fallback]; st = [fallback]; lite = [fallback]
for name, rg in RANGES.items():
    if name == 'latin-lite':
        lite.append('@font-face{font-family:"Synthetix UI";font-style:normal;font-weight:400 600;font-display:swap;src:url("%s") format("woff2");unicode-range:%s}' % (q('../fonts/subsets/SynthetixUI[wght]-latin-lite.woff2'), rg)); continue
    if name != 'latin': lite.append('@font-face{font-family:"Synthetix UI";font-style:normal;font-weight:400 600;font-display:swap;src:url("%s") format("woff2");unicode-range:%s}' % (q('../fonts/subsets/SynthetixUI[wght]-%s.woff2' % name), rg))
    vf.append('@font-face{font-family:"Synthetix UI";font-style:normal;font-weight:400 600;font-display:swap;src:url("%s") format("woff2");unicode-range:%s}' % (q('../fonts/subsets/SynthetixUI[wght]-%s.woff2' % name), rg))
    for sty, w in (('Regular', 400), ('Medium', 500), ('SemiBold', 600)):
        st.append('@font-face{font-family:"Synthetix UI";font-style:normal;font-weight:%d;font-display:swap;src:url("%s") format("woff2");unicode-range:%s}' % (w, q('../fonts/subsets/SynthetixUI-%s-%s.woff2' % (sty, name)), rg))
open(os.path.join(ROOT, 'css/synthetix-ui.css'), 'w').write(head + '/* Variable build (wght 400-600). Use synthetix-ui-static.css for the three static weights. */\n' + '\n'.join(vf) + '\n')
open(os.path.join(ROOT, 'css/synthetix-ui-lite.css'), 'w').write(head + '/* Variable build, LITE latin subset (core features + ss13 + zero/tnum; no stylistic sets, no frac/sups/subs) to stay under the 45 KB budget. */\n' + '\n'.join(lite) + '\n')
open(os.path.join(ROOT, 'css/synthetix-ui-static.css'), 'w').write(head + '/* Static weights 400/500/600. */\n' + '\n'.join(st) + '\n')

# ------------------------------------------------------------------ Swift (UNVERIFIED: not compiled in this sandbox)
cases = list(S['type'])
sw = ['// GENERATED by tokens/build_tokens.py - UNVERIFIED (not compiled; no Xcode/device in the build sandbox).', '// Fonts: add the three static TTFs to the app target and list them under UIAppFonts in Info.plist.', 'import UIKit', '',
      'public enum SynthetixType: CaseIterable {', '    case ' + ', '.join(cases), '',
      '    public struct Spec { public let size: CGFloat; public let lineHeight: CGFloat; public let psName: String; public let tracking: CGFloat; public let textStyle: UIFont.TextStyle }', '',
      '    public var spec: Spec {', '        switch self {']
ps = {'regular': 'SynthetixUI-Regular', 'medium': 'SynthetixUI-Medium', 'semibold': 'SynthetixUI-SemiBold'}
style = {'caption': '.caption1', 'label': '.subheadline', 'body': '.body', 'bodyStrong': '.body', 'amount': '.body', 'titleS': '.title3', 'titleM': '.title2', 'titleL': '.title1', 'display': '.largeTitle'}
px = lambda s: float(v(P['font']['size'][s]).replace('rem', '')) * 16
for role, t in S['type'].items():
    tr = float(v(P['font']['tracking'][t['tracking']]).replace('em', '')) * px(t['size'])
    sw.append('        case .%s: return Spec(size: %g, lineHeight: %g, psName: "%s", tracking: %.3f, textStyle: %s)' % (role, px(t['size']), float(v(P['font']['lineHeight'][t['lineHeight']]).replace('rem', '')) * 16, ps[t['weight']], tr, style[role]))
sw += ['        }', '    }', '', '    /// Dynamic Type: scales with the user\'s text-size setting through UIFontMetrics.',
       '    public func font(compatibleWith traits: UITraitCollection? = nil) -> UIFont {', '        let s = spec', '        let base = UIFont(name: s.psName, size: s.size) ?? UIFont.systemFont(ofSize: s.size)',
       '        return UIFontMetrics(forTextStyle: s.textStyle).scaledFont(for: base, compatibleWith: traits)', '    }', '}']
open(os.path.join(ROOT, 'tokens/dist/SynthetixTokens.swift'), 'w').write('\n'.join(sw) + '\n')

# ------------------------------------------------------------------ Android XML (UNVERIFIED)
xml = ['<?xml version="1.0" encoding="utf-8"?>', '<!-- GENERATED by tokens/build_tokens.py - UNVERIFIED (not built; no Android toolchain in the sandbox). Sizes in sp so they follow the user font scale. -->', '<resources>']
fam = {'regular': '@font/synthetix_ui', 'medium': '@font/synthetix_ui', 'semibold': '@font/synthetix_ui'}
for role, t in S['type'].items():
    xml.append('    <style name="SxText.%s">' % (role[0].upper() + role[1:]))
    xml.append('        <item name="android:fontFamily">@font/synthetix_ui</item>')
    xml.append('        <item name="android:textSize">%gsp</item>' % px(t['size']))
    xml.append('        <item name="android:lineHeight">%gsp</item>' % (float(v(P['font']['lineHeight'][t['lineHeight']]).replace('rem', '')) * 16))
    xml.append('        <item name="android:textFontWeight">%d</item>' % v(P['font']['weight'][t['weight']]))
    xml.append('        <item name="android:letterSpacing">%s</item>' % v(P['font']['tracking'][t['tracking']]).replace('em', ''))
    if t.get('features'): xml.append('        <item name="android:fontFeatureSettings">tnum</item>')
    xml.append('    </style>')
xml.append('</resources>')
open(os.path.join(ROOT, 'tokens/dist/synthetix_type.xml'), 'w').write('\n'.join(xml) + '\n')
ff = ['<?xml version="1.0" encoding="utf-8"?>', '<!-- res/font/synthetix_ui.xml - UNVERIFIED. Copy the TTFs as res/font/synthetix_ui_regular.ttf, _medium.ttf, _semibold.ttf (lowercase names). -->',
      '<font-family xmlns:android="http://schemas.android.com/apk/res/android">']
for sty, w in (('regular', 400), ('medium', 500), ('semibold', 600)):
    ff.append('    <font android:fontStyle="normal" android:fontWeight="%d" android:font="@font/synthetix_ui_%s"/>' % (w, sty))
ff.append('</font-family>')
open(os.path.join(ROOT, 'tokens/dist/synthetix_ui_fontfamily.xml'), 'w').write('\n'.join(ff) + '\n')
print('contrast pairs:', len(rep), '| failures:', bad, '| fallback size-adjust %.1f%%' % (adj * 100))
sys.exit(1 if bad else 0)
